  conjureMinorElementals: sp('Conjure Minor Elementals', 4, 'conjuration', [DRUID, WIZ], summon('minor elementals'), { time: 'minute', range: 90, ...conc('1 hour'), desc: 'Elementals appear and fight for you: one of CR 2, two of CR 1, and so on.' }),
  conjureWoodlandBeings: sp('Conjure Woodland Beings', 4, 'conjuration', [DRUID, RANGER], summon('fey creatures'), { range: 60, ...VSM, ...conc('1 hour'), desc: 'Fey creatures appear and fight for you: one of CR 2, two of CR 1, and so on.' }),
  controlWater: sp('Control Water', 4, 'transmutation', [CLERIC, DRUID, WIZ], utility, { range: 300, ...VSM, ...conc('10 minutes'), desc: 'Flood, part, redirect or whirl water within a 100-foot cube.' }),
  dominateBeast: sp('Dominate Beast', 4, 'enchantment', [DRUID, SORC], { type: 'save', save: 'wis', creatureType: ['beast'], advIfFighting: true, onFail: { name: 'Dominated', conditions: ['charmed'], saveEnds: 'wis', rounds: 10 } }, { ...conc('1 minute'), desc: 'A beast makes a Wisdom save or is charmed and follows your commands.' }),
  blackTentacles: sp("Evard's Black Tentacles", 4, 'conjuration', [WIZ], { type: 'zone', area: { shape: 'cube', size: 20 }, save: 'dex', damage: { dice: '3d6', type: 'bludgeoning' }, onFailZone: { name: 'Grasped', conditions: ['restrained'] }, rounds: 10 }, { range: 90, ...VSM, ...conc('1 minute'), desc: 'Writhing tentacles fill a 20-foot square: Dexterity save or 3d6 bludgeoning damage and restrained.' }),
  fabricate: sp('Fabricate', 4, 'transmutation', [WIZ, ART], utility, { time: '10min', range: 120, desc: 'Turn raw materials into finished products: a bridge from trees, clothes from flax.' }),
  giantInsect: sp('Giant Insect', 4, 'transmutation', [DRUID], summon('giant insects'), { range: 30, ...conc('10 minutes'), desc: 'Turn up to ten centipedes, three spiders, five wasps or one scorpion into giant versions that obey you.' }),
  graspingVine: sp('Grasping Vine', 4, 'conjuration', [DRUID, RANGER], { type: 'save', save: 'dex', onFail: { pull: 20 } }, { time: 'bonus', range: 30, ...conc('1 minute'), desc: 'A vine sprouts and lashes a creature within 30 feet of it: Dexterity save or be pulled 20 feet toward the vine.' }),
  hallucinatoryTerrain: sp('Hallucinatory Terrain', 4, 'illusion', [BARD, DRUID, WARLOCK, WIZ], utility, { time: '10min', range: 300, ...VSM, duration: '24 hours', desc: 'Natural terrain in a 150-foot cube looks, sounds and smells like another kind.' }),
  secretChest: sp("Leomund's Secret Chest", 4, 'conjuration', [WIZ, ART], utility, { range: 'touch', ...VSM, duration: 'Instantaneous', desc: 'Hide a chest in the Ethereal Plane and call it back with a tiny replica.' }),
  faithfulHound: sp("Mordenkainen's Faithful Hound", 4, 'conjuration', [WIZ], utility, { range: 30, ...VSM, duration: '8 hours', desc: 'An invisible watchdog barks at intruders and bites hostile creatures for 4d8 piercing damage.' }),
  privateSanctum: sp("Mordenkainen's Private Sanctum", 4, 'abjuration', [WIZ, ART], utility, { time: '10min', range: 120, ...VSM, duration: '24 hours', desc: 'Secure an area against sound, sight, scrying, teleportation and planar travel.' }),
  resilientSphere: sp("Otiluke's Resilient Sphere", 4, 'evocation', [WIZ, ART], { type: 'save', save: 'dex', onFail: { name: 'Sphere', banished: true, rounds: 10 } }, { range: 30, ...VSM, ...conc('1 minute'), desc: 'A creature makes a Dexterity save or is sealed in an indestructible sphere of force; nothing passes in or out.' }),
  polymorph: sp('Polymorph', 4, 'transmutation', [BARD, DRUID, SORC, WIZ], { type: 'save', save: 'wis', onFail: { name: 'Polymorphed', loseAction: true, rounds: 600 } }, { ...VSM, ...conc('1 hour'), desc: 'A creature becomes a beast of your choice (CR no higher than its own); unwilling targets make a Wisdom save.' }),
  staggeringSmite: sp('Staggering Smite', 4, 'evocation', [PALADIN], { type: 'buff', self: true, effect: { name: 'Staggering Smite', nextHit: { melee: true, dice: '4d6', type: 'psychic', save: 'wis', apply: { name: 'Staggered', disadvNextAttack: true, noReactions: true, rounds: 1, endsAt: 'targetEnd' } }, rounds: 10 } }, { time: 'bonus', range: 'self', components: ['V'], ...conc('1 minute'), desc: 'Your next melee weapon hit deals an extra 4d6 psychic damage; on a failed Wisdom save the target reels, losing reactions and attacking with disadvantage.' }),
